<script>document.addEventListener('DOMContentLoaded',()=>{const r=document.querySelector('[data-rating-modal]');if(r){r.showModal();r.querySelectorAll('[data-close-rating]').forEach(b=>b.addEventListener('click',()=>r.close()));r.addEventListener('click',e=>{if(e.target===r)r.close()})}const m=document.querySelector('[data-receipt-modal]'),f=m?.querySelector('iframe'),l=m?.querySelector('[data-loading]');document.querySelector('[data-open-receipt]')?.addEventListener('click',e=>{f.src=e.currentTarget.dataset.url;l.hidden=false;m.showModal()});f?.addEventListener('load',()=>l.hidden=true);m?.querySelectorAll('[data-close-receipt]').forEach(b=>b.addEventListener('click',()=>m.close()));m?.querySelector('[data-print-receipt]')?.addEventListener('click',()=>f.contentWindow?.print());const g=document.querySelector('[data-guide-modal]');document.querySelector('[data-open-guide]')?.addEventListener('click',()=>g.showModal());g?.querySelectorAll('[data-close-guide]').forEach(b=>b.addEventListener('click',()=>g.close()));[m,g].forEach(x=>x?.addEventListener('click',e=>{if(e.target===x)x.close()}))});</script>
